@startuml

class Gym {
  + computeOverallBalance(d : date) : int
  + computeAnnualBalance(year : int) : int
  + sendArrearsReminders()
  + sendMedicalCheckReminders()
}

class Customer {
  + name : string
  + surname : string
  + age : int
  + address : string
  + profession : string
}

class Subscription {
  + startDate : date
}

class MonthlySubscription extends Subscription {
}

class AnnualSubscription extends Subscription {
}

class Service {
  + name : string
  + additionalCost : float
}

class WorkoutPlan {
  + weeklyVisits : int
}

class Exercise {
  + name : string
}

class WorkoutPlanExercise {
  + repetitions : int
  + frequency : string
}

class MedicalStaff {
}

class MedicalCheckResult {
  + weight : float
  + bodyFat : float
  + electrocardiogram : string
  + restingHeartbeat : int
  + stressHeartbeat : int
}

class Diet {
  + description : string
}

Customer "1" -- "1" Subscription
Customer "1" -- "0..*" Service
Customer "1" -- "0..1" WorkoutPlan
Customer "1" -- "0..*" MedicalCheckResult
Customer "0..*" -- "1" MedicalStaff
MedicalStaff "1" -- "0..*" Diet

Subscription "0..*" -- "1" Gym
Service "0..*" -- "1" Gym

WorkoutPlan "1" -- "1..*" WorkoutPlanExercise
WorkoutPlanExercise "0..*" -- "1" Exercise
WorkoutPlan "0..*" -- "0..*" Service

@enduml

